list-view-config.query-select:
PREFIX biro: <http://purl.org/spar/biro/> PREFIX co: <http://purl.org/co/> PREFIX frbr: <http://purl.org/vocab/frbr/core#> PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#> PREFIX xsd: <http://www.w3.org/2001/XMLSchema#> PREFIX c4o: <http://purl.org/spar/c4o/>
SELECT DISTINCT ?citationCount ?countDate ?countValue ?countSource ?countSourceName
WHERE { ?subject ?property ?citationCount . ?citationCount a c4o:GlobalCitationCount .
OPTIONAL {
?subject ?property ?citationCount. ?citationCount a c4o:GlobalCitationCount .
?citationCount c4o:hasGlobalCountDate ?countDate . }
OPTIONAL {
?subject ?property ?citationCount. ?citationCount a c4o:GlobalCitationCount .
?citationCount c4o:hasGlobalCountValue ?countValue . }
OPTIONAL {
?subject ?property ?citationCount. ?citationCount a c4o:GlobalCitationCount .
?citationCount c4o:hasGlobalCountSource ?countSource . ?countSource rdfs:label ?countSourceName . } } ORDER BY DESC(?countDate)
